def clean_price(x):
    if pd.isna(x):
        return np.nan
    if isinstance(x, (int, float)):
        return float(x)
    cleaned = str(x).replace("$", "").replace(",", "")
    try:
        return float(cleaned)
    except ValueError:
        return np.nan


